/**
 * Static lookup of which 3D models (GLBs) are available per series.
 *
 * Generated by scripts/convert-dwg/03-gen-availability.py
 * from GLB filenames in catalog/glb/{Series}/.
 *
 * Storage path: {seriesCode}/{filename} in Supabase Storage bucket "models".
 *
 * When a shape+size+base combo is NOT in this map, the configurator should
 * show "model not available" instead of attempting to load a missing file.
 */

export interface ShapeAvailability {
  sizes: string[];
  bases: string[];
}

export interface SeriesAvailability {
  shapes: Record<string, ShapeAvailability>;
  defaultGlb: string;
}

